static inline int security_capable(const struct cred *cred, /* <=== security_capable */ 
				   struct user_namespace *ns, int cap)
{
	return cap_capable(cred, ns, cap, SECURITY_CAP_AUDIT);
}

static inline bool gid_lt(kgid_t left, kgid_t right) /* <=== gid_lt */ 
{
	return __kgid_val(left) < __kgid_val(right);
}

int groups_search(const struct group_info *group_info, kgid_t grp) /* <=== groups_search */ 
{
	unsigned int left, right;

	if (!group_info)
		return 0;

	left = 0;
	right = group_info->ngroups;
	while (left < right) {
		unsigned int mid = (left+right)/2;
		if (gid_gt(grp, GROUP_AT(group_info, mid)))
			left = mid + 1;
		else if (gid_lt(grp, GROUP_AT(group_info, mid)))
			right = mid;
		else
			return 1;
	}
	return 0;
}

